sql.content:

select top %(pagesize)s o.* from ( select row_number() over(order by %(orderby)s) as rownumber, * from (
    %(sql)s
) oo) o where o.rownumber>%(firstindex)s


select * from ( select ROWNUM rownumber, o.* from (
    %(sql)s   order by %(orderby)s
) o) where rownumber<=(%(firstindex)s + %(pagesize)s) and rownumber>%(firstindex)s


insert into att_tempschedule(
    employee_id, start_time, end_time, work_type, rule_flag, time_interval_id
) 
values (%(employee_id)s,'%(start_time)s','%(end_time)s',%(work_type)s, %(rule_flag)s, %(time_interval_id)s
)


insert into att_tempschedule(
    employee_id, start_time, end_time, work_type, rule_flag, time_interval_id
) 
values (%(employee_id)s, to_date('%(start_time)s','yyyy-mm-dd hh24:mi:ss'), to_date('%(end_time)s','yyyy-mm-dd hh24:mi:ss'), 
    %(work_type)s, %(rule_flag)s, %(time_interval_id)s
)


insert into att_tempschedule(
    employee_id, "start_time","end_time","work_type","rule_flag", "time_interval_id"
) 
values (%(employee_id)s,'%(start_time)s','%(end_time)s', %(work_type)s, %(rule_flag)s, %(time_interval_id)s
)
